  IEnumerator VerifyFerryRooms143(){foreach(var room in G.Map.FerryRooms143){
   var d=room.Door;Vector3 stand=d.Position;if(Mathf.Abs(d.Position.x)>1)stand+=d.Position.x<0?Vector3.right*1.0f:Vector3.left*1.0f;else stand+=Vector3.back*1.10f;
   // For the rear lounge door the approach is in the already revealed central lobby.
   if(G.Map.InteriorId=="ferry2"&&d.Position.z==-2)stand=d.Position+Vector3.forward*1.1f;
   if(Mathf.Abs(d.Position.x)<1){var path=G.Navigation.FindPath(G.Player.transform.position,stand);if(path.Count==0||Vector3.Distance(path[path.Count-1],stand)>.2f)stand=d.Position+(stand.z<d.Position.z?Vector3.forward:Vector3.back)*1.10f;}
   Check(Clear140(stand)&&Walk140(stand),"143 Walk to closed room doorway "+room.Name);F111(false,0);F111(true,.01f);Check(d.Open&&G.Vision.RoomAllowed(new Vector3(room.Area.center.x,0,room.Area.center.y)),"143 Room opens with F and changes black room to grey "+room.Name);
